function apiUrl(path) {
  const normalized = String(path || "").startsWith("/") ? String(path) : `/${path}`;
  return `${API_BASE_URL}${normalized}`;
}

function assetUrl(path) {
  return new URL(String(path || "").replace(/^\/+/, ""), document.baseURI).href;
}

