  if (Number.isFinite(width) && width > 0) fieldCanvasCssWidth = width;
  if (Number.isFinite(height) && height > 0) fieldCanvasCssHeight = height;
  if (Number.isFinite(Number(rect?.top))) fieldCanvasCssTop = Number(rect.top);
