const AUTHORED_THROW_DIRECTIONS = Object.freeze(["front", "left", "right", "back"]);
const AUTHORED_THROW_KEYS = Object.freeze(["prepare", "release", "follow", "recover"]);
const AUTHORED_THROW_LATCHES = new WeakMap();

function authoredThrowFrame(profile, action, progress) {
  if (action.variant === "prepare") return "prepare";
  let selected = profile.releaseKeys[0];
  for (const entry of profile.releaseKeys) if (progress >= entry.at) selected = entry;
  return selected.key;
}

function authoredThrowPoseReady(pose, image) {
  const rect = pose?.sourceRect;
  return Boolean(image?.complete && Number(image.naturalWidth) > 0 && Number(image.naturalHeight) > 0
    && rect && Number.isFinite(rect.x) && Number.isFinite(rect.y)
    && Number.isFinite(rect.width) && Number.isFinite(rect.height)
    && rect.x >= 0 && rect.y >= 0 && rect.width > 0 && rect.height > 0
    && rect.x + rect.width <= image.naturalWidth && rect.y + rect.height <= image.naturalHeight
    && Number.isFinite(pose?.origin?.x) && Number.isFinite(pose?.origin?.y)
    && Number.isFinite(pose?.ground?.x) && Number.isFinite(pose?.ground?.y)
    && Number.isFinite(pose?.scale) && pose.scale > 0);
}

function drawAuthoredThrowPose(player, data, ghost, action, atlasId, progress) {
  const profile = AUTHORED_THROW_PROFILES[atlasId];
  if (player.isBot || !profile || action?.kind !== "throw") return false;
  const preparing = action.variant === "prepare";
  if (!preparing && action.motionId !== "action-item-throw") return false;
  const facing = facingFor(player, motionFor(player, data));
  const direction = facing === "down" ? "front" : facing === "up" ? "back" : facing;
  if (!AUTHORED_THROW_DIRECTIONS.includes(direction)) return false;
  let owner, token;
  if (preparing) {
    if (player.id !== data.selfId || !state.throwTargeting.active) return false;
    owner = state.throwTargeting;
    token = ["prepare", owner.startedAt, owner.itemId, owner.chargeId].join("|");
  } else {
    token = [action.startedAt, action.sourceEffectId, action.motionId, action.kind].join("|");
    owner = state.characterActions?.get(player.id);
    if (!owner || [owner.startedAt, owner.sourceEffectId, owner.motionId, owner.kind].join("|") !== token) return false;
  }
  let latch = AUTHORED_THROW_LATCHES.get(owner);
  // The targeting session or admitted action owns one readiness decision, even on failure.
  // Loading another direction later must never replace the art halfway through this action.
  if (!latch) {
    const sequences = Object.fromEntries(AUTHORED_THROW_DIRECTIONS.map((dir) => [dir, AUTHORED_THROW_KEYS.map((key) => {
      const pose = profile.directions[dir]?.[key], image = state.textures.authoredThrowMotions?.[atlasId]?.[dir]?.[key];
      return authoredThrowPoseReady(pose, image) ? { pose, image } : null;
    })]));
    latch = { token, identity: atlasId, sequences: Object.values(sequences).every(sequence => sequence.every(Boolean)) ? sequences : null };
    AUTHORED_THROW_LATCHES.set(owner, latch);
  }
  if (latch.token !== token || latch.identity !== atlasId || !latch.sequences) return false;
  if (ctx.globalAlpha <= 0) return true;
  const key = authoredThrowFrame(profile, action, progress);
  const selected = latch.sequences[direction][AUTHORED_THROW_KEYS.indexOf(key)];
  if (!selected) return false;
  const { pose, image } = selected, rect = pose.sourceRect;
  ctx.save();
  try {
    ctx.imageSmoothingEnabled = true;
    ctx.imageSmoothingQuality = IMAGE_SMOOTHING_QUALITY;
    ctx.drawImage(image, rect.x, rect.y, rect.width, rect.height,
      pose.ground.x - pose.origin.x * pose.scale, pose.ground.y - pose.origin.y * pose.scale,
      rect.width * pose.scale, rect.height * pose.scale);
  } finally { ctx.restore(); }
  drawNameplate(player, ghost, -78);
  return true;
}

