let HEAL_E_SFX_PLAYER = null;
let HEAL_E_SFX_CONTEXT = null;
let HEAL_E_SFX_ACTIVE = null;
let BARRIER_R07_SFX_PLAYER = null;
let BARRIER_R07_SFX_CONTEXT = null;

function commitBarrierR07SoundFrame(data, receipts) {
  if (!Array.isArray(receipts) || !receipts.length ||
      !window.DvaWebGPUBarrierProR07Sfx?.createPlayer ||
      !window.DvaWebGPUBarrierE?.resolveEvent ||
      state.screen !== 'game' || document.hidden || IS_VERIFICATION_MODE ||
      state.audio.muted || !state.audio.unlocked || isSensoryBlocked(data) ||
      state.audio.context?.state !== 'running' ||
      !(state.audio.master?.gain?.value > 0)) return;
  if (BARRIER_R07_SFX_CONTEXT !== state.audio.context) {
    BARRIER_R07_SFX_PLAYER?.destroy();
    BARRIER_R07_SFX_CONTEXT = state.audio.context;
    BARRIER_R07_SFX_PLAYER = window.DvaWebGPUBarrierProR07Sfx.createPlayer({
      context: state.audio.context, destination: state.audio.master });
  }
  const roomId = String(data?.roomId || '');
  const roomGeneration = state.roomSessionGeneration;
  const sourceFor = receipt => (state.magicEffects || []).find(effect =>
    String(effect?.id) === String(receipt?.effectId) &&
    window.DvaWebGPUBarrierE.resolveEvent(effect)?.variant === receipt?.variant);
  const selected = receipts.filter(receipt =>
    receipt?.roomId === roomId && String(receipt?.ownerId || '') &&
    Number.isFinite(receipt.progress) && receipt.progress >= 0 && receipt.progress < 1 &&
    sourceFor(receipt));
  if (!selected.length) return;
  for (const receipt of selected) {
    BARRIER_R07_SFX_PLAYER.play([{ roomId, roomGeneration,
      eventId: String(receipt.effectId), event: receipt.variant }], {
      verify: IS_VERIFICATION_MODE, muted: state.audio.muted,
      isCurrent: () => {
        const source = sourceFor(receipt);
        const elapsed = source && eEffectNow(source, state.data, performance.now()) - source.startedAt;
        return state.roomId === roomId && state.roomSessionGeneration === roomGeneration &&
          state.screen === 'game' && !document.hidden && !state.audio.muted &&
          state.audio.context === BARRIER_R07_SFX_CONTEXT &&
          state.audio.context?.state === 'running' && !isSensoryBlocked(state.data) &&
          elapsed >= 0 && elapsed <
            (receipt.variant === 'create' || receipt.variant === 'absorb' ? 650 : 480);
      } }).catch(error => {
        document.body.dataset.barrierR07SfxError = String(error?.message || error).slice(0, 180);
      });
  }
}


function stopHealESfx() {
  HEAL_E_SFX_PLAYER?.stop();
  HEAL_E_SFX_ACTIVE = null;
}
function healESfxSource(data, id, nowMs = state.frameNow || performance.now()) {
  const effect = state.magicEffects.find(item => item.type === 'flora' &&
    String(item.id) === id && String(item.playerId) === String(data?.selfId));
  const owner = data?.players?.find(player => String(player.id) === String(data.selfId));
  const elapsed = nowMs - effect?.startedAt;
  if (!effect || effect.cancelled || !owner?.alive || owner.ejected || owner.inVent || owner.invisible ||
      owner.visible === false ||
      data.phase !== 'playing' || !(elapsed >= 0 && elapsed < Math.min(12000, effect.duration)) ||
      (effect.actorClockRoomId && String(effect.actorClockRoomId) !== String(data.roomId)) ||
      (elapsed >= 1860 && !(Number(data.self?.timedAccelerationStacks?.flora?.endsAt) > estimatedServerNow(data)))) return null;
  return { effect, phaseSeconds: elapsed / 1000 };
}
function commitHealESfxVisualFrame(data, receipts) {
  // Only a submitted, selected visible main frame authorizes the adopted sound.
  if (state.screen !== 'game' || document.hidden || state.audio.muted ||
      isSensoryBlocked(data) || !state.audio.unlocked ||
      state.audio.context?.state !== 'running' || !(state.audio.master?.gain?.value > 0) ||
      !window.DvaHealSparkleSfx?.createPlayer) { stopHealESfx(); return; }
  const receipt = [...(receipts || [])].reverse().find(item => String(item.playerId) === String(data.selfId));
  const source = receipt && healESfxSource(data, receipt.effectId);
  if (!source) { stopHealESfx(); return; }
  const key = `${data.roomId}:${state.roomSessionGeneration}:${receipt.effectId}`;
  const actor = data.players?.find(player => String(player.id) === String(receipt.playerId));
  const actorRate = actor ? displayETimeScale(actor, data) : 1;
  if (HEAL_E_SFX_ACTIVE?.key === key) {
    HEAL_E_SFX_PLAYER.update({ actorElapsedSeconds: receipt.actorSeconds, actorRate });
    return;
  }
  if (HEAL_E_SFX_CONTEXT !== state.audio.context) {
    HEAL_E_SFX_PLAYER?.destroy();
    HEAL_E_SFX_CONTEXT = state.audio.context;
    HEAL_E_SFX_PLAYER = window.DvaHealSparkleSfx.createPlayer({
      context: HEAL_E_SFX_CONTEXT, destination: state.audio.master, syncActorClock: true });
  }
  // Resume after hiding/muting joins the current phase rather than replaying onset.
  // First-use synthesis can take time; read wall time after it, not before it.
  const currentSource = healESfxSource(data, receipt.effectId, performance.now());
  if (!currentSource) { stopHealESfx(); return; }
  if (HEAL_E_SFX_PLAYER.start({ eventId: key, loop: true,
      phaseSeconds: currentSource.phaseSeconds, actorElapsedSeconds: receipt.actorSeconds,
      actorRate, volume: 1 }))
    HEAL_E_SFX_ACTIVE = { key, effectId: receipt.effectId, roomId: String(data.roomId),
      generation: state.roomSessionGeneration };
}
