// as a diagnostic selector only; it no longer gates renderer ownership.
const WEBGPU_MAIN_OWNER = true;
const WEBGPU_MAIN_VERIFY_ROUTE = IS_VERIFICATION_MODE && URL_PARAMETERS.get("webgpuMain") === "1";
