function itemUseMotionProfile(itemId) {
  return ITEM_USE_MOTION_PROFILES[String(itemId || "")] || null;
}

function itemUseMotionProfileForMotion(motionId) {
  return ITEM_USE_MOTION_BY_ID[String(motionId || "")] || null;
}

function itemUseMotionFrame(profile, progress) {
  if (!profile?.keyframes?.length) return null;
  const elapsed = Math.max(0, Math.min(1, Number(progress) || 0)) * profile.duration;
  let selected = profile.keyframes[0];
  for (const frame of profile.keyframes) if (elapsed >= frame.atMs) selected = frame;
  return selected;
}

function itemUsePoseAsset(profile, skinId, direction, frameKey) { return profile?.assets?.[skinId]?.[direction]?.[frameKey] || null; }
function itemUsePoseHasRaster(pose) { return Boolean(pose?.assetPath && pose?.sourceRect && pose?.origin && pose?.ground && Number(pose?.scale) > 0); }
function resolveItemUsePose(profile, skinId, requestedDirection, frameKey) {
  const direction = ITEM_USE_POSE_DIRECTIONS.includes(requestedDirection) ? requestedDirection : "front";
  const exact = itemUsePoseAsset(profile, skinId, direction, frameKey);
  if (itemUsePoseHasRaster(exact)) return { pose: exact, direction, fallback: false };
  // Explicitly authored front-only item actions may fall back only for the
  // same identity. This never rotates or mirrors the art or changes game facing.
  // Unsupported items and identities retain their existing rejection path.
  if (profile?.itemId !== "antidote" && profile?.itemId !== "mineral-water" && profile?.itemId !== "seawater") return null;
  const front = itemUsePoseAsset(profile, skinId, "front", frameKey);
  return itemUsePoseHasRaster(front) ? { pose: front, direction: "front", fallback: direction !== "front" } : null;
}

function itemUseCharacterAction(itemId) {
  const profile = itemUseMotionProfile(itemId);
  return profile ? { kind: "interact", duration: profile.duration, motionId: profile.motionId, itemId: profile.itemId } : null;
}

function triggerCharacterAction(playerId, kind, duration = CHARACTER_ACTION_DURATION[kind] || 700, startedAt = state.frameNow || performance.now(), sourceEffectId = "", variant = "", motionId = kind, presentation = null) {
  if (!playerId || !kind) return;
  if(preserveBotSmgReloadPriority(playerId,kind,variant))return;
  if(preserveBotSniperReloadPriority(playerId,kind,variant))return;
  if(preserveBotAssaultReloadPriority(playerId,kind,variant))return;
  if(preserveAuthoredHandgunPriority(playerId,kind,variant))return;
  const reloadPlayer=state.data?.players?.find(p=>p.id===playerId);
  const existingBody=state.characterActions.get(playerId);
  if (existingBody?.motionId === 'flora-sunbeam' && motionId !== 'flora-sunbeam' &&
      Number.isFinite(sunbeamActorVisualElapsed(existingBody, state.data)) &&
      sunbeamActorVisualElapsed(existingBody, state.data) <
        Number(existingBody.sunbeamEffectDurationMs || 1200)) return;
  if(motionId==="action-reload"&&((variant==="handgun:complete"&&authoredHandgunReloadEligible(reloadPlayer,state.data))||(variant==="smg:complete"&&authoredSmgReloadEligible(reloadPlayer,state.data))||(variant==="assault:complete"&&authoredAssaultReloadEligible(reloadPlayer,state.data))||(variant==="taser:complete"&&authoredSophiaTaserReloadEligible(reloadPlayer,state.data))||(variant==="taser:complete"&&authoredTaserReloadEligible(reloadPlayer,state.data))||(variant==="sniper:complete"&&authoredSniperReloadEligible(reloadPlayer,state.data)))&&existingBody&&existingBody.motionId!=="action-reload")return;
  const createdAction = {
    kind,
    startedAt,
    duration: Math.max(120, Number(duration) || 700),
    sourceEffectId,
    variant: String(variant || ""),
    motionId: String(motionId || kind),
    ...(presentation && typeof presentation === "object" ? presentation : {})
  };
  state.characterActions.set(playerId, createdAction);
  // Decode admission is intentionally one-shot at action start, before render.
  // Missing art remains the existing generic whole-action presentation.
  admitAuthoredSunbeamAction(reloadPlayer, createdAction);
}

