  if(!player||!authoredHandgunFireReady(authoredHandgunFireIdentity(player,state.data),String(variant).split(':')[0])||!action||['shoot','reload','focus'].includes(action.kind))return false;
  const elapsed=clamp((state.frameNow||performance.now())-(Number(action.lastSampleAt)||Number(action.startedAt)||0),0,100);
  const progress=(Number(action.sampledProgress)||0)+elapsed*physicalMotionRateFor(player)/Math.max(1,action.duration);
  if(progress>=1)return false;
