    const recoil = Math.sin(clamp((progress - 0.26) / 0.42, 0, 1) * Math.PI);
    ctx.translate(facing * (-5.5 * brace - 15 * recoil) * motionScale, (5 * brace + 1.5 * recoil) * motionScale);
    ctx.rotate(-facing * (0.052 * brace + 0.075 * recoil) * motionScale);
