const criticalMapImageLoads = new WeakMap();
const criticalFacilityImageLoads = new WeakMap();

function loadCriticalFacilityTexture(image, source) {
  const existing = criticalFacilityImageLoads.get(image);
  if (existing?.source === source && existing.status !== "cancelled") return;
  image.fetchPriority = "high";
  let retries = 0;
  let retryTimer = null;
  let watchdog = null;
  const load = { source, status: "loading" };
  const clearTimer = (timer) => {
    if (timer !== null) window.clearTimeout(timer);
  };
  const clearWatchdog = () => {
    if (watchdog !== null) window.clearTimeout(watchdog);
    watchdog = null;
  };
  const detach = () => {
    image.removeEventListener("load", onLoad);
    image.removeEventListener("error", onError);
  };
  const fail = () => {
    if (load.status !== "loading") return;
    load.status = "failed";
    clearWatchdog();
    clearTimer(retryTimer);
    retryTimer = null;
    detach();
    setWebGPUMainFailure(new Error(`Required facility task material could not be loaded: ${source}`));
  };
  const retry = () => {
    if (load.status !== "loading") return;
    clearWatchdog();
    if (image.complete && image.naturalWidth > 0) {
      load.status = "loaded";
      detach();
      return;
    }
    if (retryTimer !== null) return;
    if (retries >= 3) {
      fail();
      return;
    }
    retries += 1;
    retryTimer = window.setTimeout(() => {
      retryTimer = null;
      start();
    }, [300, 900, 2000][retries - 1]);
  };
  const onLoad = () => {
    if (load.status !== "loading") return;
    if (image.naturalWidth > 0) {
      clearWatchdog();
      load.status = "loaded";
      detach();
    } else retry();
  };
  const onError = () => { if (load.status === "loading") retry(); };
  const start = () => {
    if (load.status !== "loading") return;
    const separator = source.includes("?") ? "&" : "?";
    image.src = retries ? `${source}${separator}facilityRetry=${retries}` : source;
    watchdog = window.setTimeout(() => {
      if (!(image.complete && image.naturalWidth > 0)) retry();
    }, 15000);
  };
  criticalFacilityImageLoads.set(image, load);
  image.addEventListener("load", onLoad);
  image.addEventListener("error", onError);
  start();
}

function loadCriticalMapTexture(image, source) {
  const existing = criticalMapImageLoads.get(image);
  if (existing?.source === source && existing.status !== "cancelled") return existing.cancel;
  existing?.cancel();
  image.fetchPriority = "high";
  let retries = 0;
  let retryTimer = null;
  let watchdog = null;
  const load = { source, status: "loading", cancel: null };
  const clearTimer = (timer) => {
    if (timer !== null) window.clearTimeout(timer);
  };
  const clearWatchdog = () => {
    if (watchdog !== null) window.clearTimeout(watchdog);
    watchdog = null;
  };
  const onLoad = () => {
    if (load.status !== "loading") return;
    if (image.naturalWidth > 0) {
      clearWatchdog();
      load.status = "loaded";
    } else retry();
  };
  const onError = () => {
    if (load.status === "loading") retry();
  };
  load.cancel = () => {
    if (load.status !== "loading") return;
    load.status = "cancelled";
    clearWatchdog();
    clearTimer(retryTimer);
    retryTimer = null;
    image.removeEventListener("load", onLoad);
    image.removeEventListener("error", onError);
    // Setting src to the empty string aborts a stale in-flight request. A
    // later selection change can create a fresh load with the normal retries.
    image.removeAttribute("src");
  };
  criticalMapImageLoads.set(image, load);
  const retry = () => {
    if (load.status !== "loading") return;
    clearWatchdog();
    if (image.complete && image.naturalWidth > 0) return;
    if (retryTimer !== null) return;
    if (retries >= 3) {
      load.status = "failed";
      image.removeEventListener("load", onLoad);
      image.removeEventListener("error", onError);
      setWebGPUMainFailure(new Error("Required map image could not be loaded after retries"));
      return;
    }
    retries += 1;
    retryTimer = window.setTimeout(() => {
      retryTimer = null;
      start();
    }, [300, 900, 2000][retries - 1]);
  };
  const start = () => {
    if (load.status !== "loading") return;
    const separator = source.includes("?") ? "&" : "?";
    image.src = retries ? `${source}${separator}mapRetry=${retries}` : source;
    watchdog = window.setTimeout(() => {
      if (!(image.complete && image.naturalWidth > 0)) retry();
    }, 15000);
  };
  image.addEventListener("load", onLoad);
  image.addEventListener("error", onError);
  start();
  return load.cancel;
}

let selectedMapPreload = null;
function preloadSelectedRequiredMap(value = els.mapSelect?.value) {
  const textures = state.textures;
  if (!textures) return;
  const mapId = normalizeMatchmakingMapId(value);
  if (selectedMapPreload?.mapId === mapId) return;
  // A changed selection invalidates only the outstanding fetch/retry for the
  // old map. Completed immutable images remain cached for reuse.
  selectedMapPreload?.cancel?.();
  const image = textures.fullMapComposites?.[mapId];
  const source = (textures.pendingSources || []).find(([entry]) => entry === image)?.[1];
  if (!image || !source) {
    selectedMapPreload = { mapId, cancel: null };
    return;
  }
  const cancel = loadCriticalMapTexture(image, source);
  selectedMapPreload = { mapId, cancel };
}

// Keep the title's first character sheets ahead of the large optional texture
// set. Image identity is shared with the normal renderer and URL lookup uses
// pendingSources so this never creates duplicate requests.
function startGameplayOptionalTexture(textures, image, source) {
  if (!image || !source) return false;
  textures.gameplayLoadStarted ||= new Set();
  if (textures.gameplayLoadStarted.has(image)) return false;
  textures.gameplayLoadStarted.add(image);
  if (image.complete && image.naturalWidth > 0) return false;
  if (image.src) return false;
  image.src = source;
  return true;
}

function preloadSelectedAuthoredWalkSprites(value = els.skinSelect?.value) {
  const textures = state.textures;
  if (!textures) return;
  const humanIdentity = renderSkinAssetId(value);
  textures.gameplayLoadStarted ||= new Set();
  for (const identity of [humanIdentity, "male-bot"]) {
    const directions = textures.authoredCharacterMotion?.[identity];
    for (const direction of ["front", "left", "right", "back"]) {
      const image = directions?.[direction]?.walk;
      if (!image) continue;
      const source = (textures.pendingSources || []).find(([entry]) => entry === image)?.[1];
      if (!source || image.complete && image.naturalWidth > 0 || image.src) {
        if (source && (image.src || image.complete && image.naturalWidth > 0)) {
          textures.gameplayLoadStarted.add(image);
        }
        continue;
      }
      image.fetchPriority = "high";
      startGameplayOptionalTexture(textures, image, source);
    }
  }
}

const OPTIONAL_GAMEPLAY_IMAGE_STARTS_PER_TASK = 8;

function scheduleGameplayTextureBatch(textures) {
  if (!textures?.gameplayLoadQueue?.length || textures.gameplayLoadScheduled) return;
  textures.gameplayLoadScheduled = true;
  window.setTimeout(() => {
    textures.gameplayLoadScheduled = false;
    const queue = textures.gameplayLoadQueue;
    let started = 0;
    while (textures.gameplayLoadCursor < queue.length &&
        started < OPTIONAL_GAMEPLAY_IMAGE_STARTS_PER_TASK) {
      const [image, source] = queue[textures.gameplayLoadCursor++];
      if (startGameplayOptionalTexture(textures, image, source)) started += 1;
    }
    if (textures.gameplayLoadCursor < queue.length) scheduleGameplayTextureBatch(textures);
  }, 0);
}

function loadGameplayTextures() {
  const textures = state.textures;
  if (!textures) return;
  preloadSelectedAuthoredWalkSprites();
  if (textures.gameplayLoaded) return;
  textures.gameplayLoaded = true;
  preloadSelectedRequiredMap(els.mapSelect?.value);
  const criticalMaps = new Set(Object.values(textures.fullMapComposites || {}));
  for (const [entry, source] of textures.pendingSources || []) {
    if (criticalMaps.has(entry)) loadCriticalMapTexture(entry, source);
  }
  // These two bounded task-station materials are required for the facility
  // scene and must begin before the large optional gameplay asset queue.
  const criticalFacility = new Set([
    textures.taskUploadDigital,
    textures.taskDownloadDigital
  ]);
  for (const [entry, source] of textures.pendingSources || []) {
    if (criticalFacility.has(entry)) loadCriticalFacilityTexture(entry, source);
  }
  textures.gameplayLoadStarted ||= new Set();
  textures.gameplayLoadQueue = [];
  textures.gameplayLoadCursor = 0;
  for (const [entry, source] of textures.pendingSources || []) {
    if (criticalMaps.has(entry) || criticalFacility.has(entry)) continue;
    if (entry.src || entry.complete && entry.naturalWidth > 0) {
      textures.gameplayLoadStarted.add(entry);
      continue;
    }
    textures.gameplayLoadQueue.push([entry, source]);
  }
  scheduleGameplayTextureBatch(textures);
}

